}

private data class ErrorRange(val from: Long, val to: Long, val cls: ErrorClass, val retryable: Boolean, val action: String)

private val ERROR_RANGES: List<ErrorRange> = listOf(
    ErrorRange(1000L, 1099L, ErrorClass.Protocol, false, "fatal_upgrade"),
    ErrorRange(1100L, 1199L, ErrorClass.Auth, false, "reauthenticate"),
    ErrorRange(1200L, 1299L, ErrorClass.Permission, false, "surface_denied"),
    ErrorRange(1300L, 1399L, ErrorClass.Validation, false, "log_bug"),
    ErrorRange(1400L, 1499L, ErrorClass.RateLimit, true, "retry_after"),
    ErrorRange(1500L, 1599L, ErrorClass.State, false, "reconcile"),
    ErrorRange(1600L, 1699L, ErrorClass.Server, true, "backoff_retry"),
