data class UserProfile(
    val userId: Id,
    /** MGO-XXXXXXXX, immutable, shareable */
    val publicId: String,
    val username: String,
    val displayName: String,
    val avatarUrl: String? = null,
    val bio: String? = null,
    val country: String? = null,
    val language: String? = null,
    val level: Long? = null,
    val presence: PresenceState? = null,
    val badges: List<String>? = null,
    val verified: Boolean? = null,
    val customStatus: String? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(userId)
        w.str(publicId)
        w.str(username)
        w.str(displayName)
        var present = 0
        if (avatarUrl != null) present++
        if (bio != null) present++
        if (country != null) present++
        if (language != null) present++
        if (level != null) present++
        if (presence != null) present++
        if (badges != null) present++
        if (verified != null) present++
        if (customStatus != null) present++
        w.u32(present)
        if (avatarUrl != null) {
            val value = avatarUrl
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (bio != null) {
            val value = bio
            w.optional(2) { w ->
                w.str(value)
            }
        }
        if (country != null) {
            val value = country
            w.optional(3) { w ->
                w.str(value)
            }
        }
        if (language != null) {
            val value = language
            w.optional(4) { w ->
                w.str(value)
            }
        }
        if (level != null) {
            val value = level
            w.optional(5) { w ->
                w.u32(value)
            }
        }
        if (presence != null) {
            val value = presence
            w.optional(6) { w ->
                w.u32(value.toWire())
            }
        }
        if (badges != null) {
            val value = badges
            w.optional(7) { w ->
                w.listLen(value.size)
                for (item in value) { w.str(item) }
            }
        }
        if (verified != null) {
            val value = verified
            w.optional(8) { w ->
                w.bool(value)
            }
        }
        if (customStatus != null) {
            val value = customStatus
            w.optional(9) { w ->
                w.str(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): UserProfile {
            r.enter()
            val userId = r.id()
            val publicId = r.str()
            val username = r.str()
            val displayName = r.str()
            var avatarUrl: String? = null
            var bio: String? = null
            var country: String? = null
            var language: String? = null
            var level: Long? = null
            var presence: PresenceState? = null
            var badges: List<String>? = null
            var verified: Boolean? = null
            var customStatus: String? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> avatarUrl = sub.str()
                    2L -> bio = sub.str()
                    3L -> country = sub.str()
                    4L -> language = sub.str()
                    5L -> level = sub.u32()
                    6L -> presence = PresenceState.fromWire(sub.u32())
                    7L -> badges = run { val n = sub.listLen(); val acc = ArrayList<String>(n); for (i in 0 until n) acc.add(sub.str()); acc }
                    8L -> verified = sub.bool()
                    9L -> customStatus = sub.str()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return UserProfile(userId, publicId, username, displayName, avatarUrl, bio, country, language, level, presence, badges, verified, customStatus)
        }
    }
}

