data class ConversationSummary(
    val conversationId: Id,
    val kind: ConversationKind,
    val encryption: EncryptionMode,
    val lastSeq: Long,
    val readSeq: Long,
    val title: String? = null,
    val avatarUrl: String? = null,
    val members: List<Id>? = null,
    val lastMessage: MessageEvent? = null,
    val mutedUntil: Long? = null,
    val pinned: Boolean? = null,
    val archived: Boolean? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(conversationId)
        w.u32(kind.toWire())
        w.u32(encryption.toWire())
        w.u64(lastSeq)
        w.u64(readSeq)
        var present = 0
        if (title != null) present++
        if (avatarUrl != null) present++
        if (members != null) present++
        if (lastMessage != null) present++
        if (mutedUntil != null) present++
        if (pinned != null) present++
        if (archived != null) present++
        w.u32(present)
        if (title != null) {
            val value = title
            w.optional(1) { w ->
                w.str(value)
            }
        }
        if (avatarUrl != null) {
            val value = avatarUrl
            w.optional(2) { w ->
                w.str(value)
            }
        }
        if (members != null) {
            val value = members
            w.optional(3) { w ->
                w.listLen(value.size)
                for (item in value) { w.id(item) }
            }
        }
        if (lastMessage != null) {
            val value = lastMessage
            w.optional(4) { w ->
                value.encode(w)
            }
        }
        if (mutedUntil != null) {
            val value = mutedUntil
            w.optional(5) { w ->
                w.timestamp(value)
            }
        }
        if (pinned != null) {
            val value = pinned
            w.optional(6) { w ->
                w.bool(value)
            }
        }
        if (archived != null) {
            val value = archived
            w.optional(7) { w ->
                w.bool(value)
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): ConversationSummary {
            r.enter()
            val conversationId = r.id()
            val kind = ConversationKind.fromWire(r.u32())
            val encryption = EncryptionMode.fromWire(r.u32())
            val lastSeq = r.u64()
            val readSeq = r.u64()
            var title: String? = null
            var avatarUrl: String? = null
            var members: List<Id>? = null
            var lastMessage: MessageEvent? = null
            var mutedUntil: Long? = null
            var pinned: Boolean? = null
            var archived: Boolean? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> title = sub.str()
                    2L -> avatarUrl = sub.str()
                    3L -> members = run { val n = sub.listLen(); val acc = ArrayList<Id>(n); for (i in 0 until n) acc.add(sub.id()); acc }
                    4L -> lastMessage = MessageEvent.decode(sub)
                    5L -> mutedUntil = sub.timestamp()
                    6L -> pinned = sub.bool()
                    7L -> archived = sub.bool()
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return ConversationSummary(conversationId, kind, encryption, lastSeq, readSeq, title, avatarUrl, members, lastMessage, mutedUntil, pinned, archived)
        }
    }
}

