        w.listLen(profiles.size)
        for (item in profiles) { item.encode(w) }
        w.u32(0)
        w.leave()
    }

    companion object {
        fun decode(r: Reader): ProfileResponse {
            r.enter()
            val profiles = run { val n = r.listLen(); val acc = ArrayList<UserProfile>(n); for (i in 0 until n) acc.add(UserProfile.decode(r)); acc }
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                r.optional() // no optional fields in this build; a newer peer's are skipped by length
            }
            r.leave()
            return ProfileResponse(profiles)
        }
    }
}

