/** An intent. The server decides the outcome (brief 89). */
data class GameAction(
    val gameId: Id,
    val roomId: Id,
    /** Monotonic per game per player; replays are detected */
    val actionId: Long,
    val action: String,
    val args: List<String>? = null,
) {
    fun encode(w: Writer) {
        w.enter()
        w.id(gameId)
        w.id(roomId)
        w.u64(actionId)
        w.str(action)
        var present = 0
        if (args != null) present++
        w.u32(present)
        if (args != null) {
            val value = args
            w.optional(1) { w ->
                w.listLen(value.size)
                for (item in value) { w.str(item) }
            }
        }
        w.leave()
    }

    companion object {
        fun decode(r: Reader): GameAction {
            r.enter()
            val gameId = r.id()
            val roomId = r.id()
            val actionId = r.u64()
            val action = r.str()
            var args: List<String>? = null
            val optionalCount = r.u32()
            for (i in 0L until optionalCount) {
                val (fieldId, sub) = r.optional()
                when (fieldId) {
                    1L -> args = run { val n = sub.listLen(); val acc = ArrayList<String>(n); for (i in 0 until n) acc.add(sub.str()); acc }
                    else -> {} // unknown optional field: skipped by length (forward compatibility)
                }
            }
            r.leave()
            return GameAction(gameId, roomId, actionId, action, args)
        }
    }
}

