/** Delivery class, deciding what happens when a session queue is full. */
enum class DeliveryClass { Critical, Coalescable, Droppable }
/** Minimum session state an opcode requires. */
enum class AuthLevel { None, User, Bot, Server }
/** Direction an opcode may legally travel. */
enum class Direction { ClientToServer, ServerToClient, Both }

/** Every opcode in MWP/1. */
object Op {
    /** Handshake. Also carries optional token and resume. */
    const val HELLO: Long = 1L
    const val PING: Long = 2L
    /** Cumulative watermark; retires held frames. */
    const val ACK: Long = 3L
    /** Standalone (non-correlated) error, usually fatal. */
    const val ERROR: Long = 4L
    const val RECONNECT_HINT: Long = 5L
    const val AUTHENTICATE: Long = 6L
    const val SUBSCRIBE: Long = 7L
    const val UNSUBSCRIBE: Long = 8L
    /** Publish public identity/prekeys for this device. */
    const val KEY_PUBLISH: Long = 16L
    const val KEY_BUNDLE_FETCH: Long = 17L
    const val MESSAGE_SEND: Long = 32L
    const val MESSAGE_EVENT: Long = 33L
    const val MESSAGE_RECEIPT: Long = 34L
    const val MESSAGE_DELETE: Long = 35L
    const val SYNC: Long = 36L
    const val CONVERSATION_LIST: Long = 37L
    const val CONVERSATION_CREATE: Long = 38L
    const val TYPING: Long = 39L
    const val PRESENCE_SET: Long = 64L
    const val PRESENCE_EVENT: Long = 65L
    const val ROOM_JOIN: Long = 80L
    const val ROOM_LEAVE: Long = 81L
    const val ROOM_LIST: Long = 82L
    const val ROOM_MEMBER_EVENT: Long = 83L
    const val ROOM_STATE_EVENT: Long = 84L
    const val PROFILE_FETCH: Long = 112L
    const val NOTIFICATION_EVENT: Long = 144L
    const val GAME_ACTION: Long = 176L
    const val GAME_EVENT: Long = 177L
}

/** Static metadata for one opcode: its rate-limit cost, delivery class, required auth, and shape. */
data class OpcodeMeta(
    val code: Long,
    val name: String,
    val cost: Int,
    val cls: DeliveryClass,
    val auth: AuthLevel,
    val direction: Direction,
    val ackRequired: Boolean,
    val payload: String,
    val response: String? = null,
    val coalesceKey: String? = null,
)

val OPCODES: Map<Long, OpcodeMeta> = mapOf(
    1L to OpcodeMeta(1L, "HELLO", 5, DeliveryClass.Critical, AuthLevel.None, Direction.ClientToServer, false, "Hello", "Welcome", null),
